// Tiny WebVTT parser — handles the common shape (WEBVTT header,
// blank-line separated cues, "00:00.000 --> 00:00.000" timestamps with
// optional hours, multi-line text). Cue settings, voice tags, NOTE
// blocks are preserved as plain text rather than parsed; that's enough
// for academy use (uploaded VTT generated by Whisper / hand-edited
// from SRT).
//
// Lives in its own module so non-React-Native consumers (tests, future
// admin previews) can import without dragging in the player overlay.

export type Cue = { start: number; end: number; text: string }

const TS_RE =
    /^(\d{1,2}:)?(\d{1,2}):(\d{1,2})[.,](\d{1,3})\s+-->\s+(\d{1,2}:)?(\d{1,2}):(\d{1,2})[.,](\d{1,3})/

const toSeconds = (parts: {
    h?: string
    m: string
    s: string
    ms: string
}): number => {
    const h = parts.h ? parseInt(parts.h.replace(':', ''), 10) : 0
    const m = parseInt(parts.m, 10)
    const s = parseInt(parts.s, 10)
    const ms = parseInt(parts.ms.padEnd(3, '0').slice(0, 3), 10)
    return h * 3600 + m * 60 + s + ms / 1000
}

export const parseVtt = (raw: string): Cue[] => {
    const cues: Cue[] = []
    const cleaned = raw.replace(/^\uFEFF/, '').replace(/\r/g, '')
    const blocks = cleaned.split(/\n\n+/)
    for (const block of blocks) {
        const lines = block.split('\n').filter((line) => line.length > 0)
        if (lines.length === 0) continue
        const tsLine = lines.find((line) => TS_RE.test(line))
        if (!tsLine) continue
        const match = TS_RE.exec(tsLine)
        if (!match) continue
        const start = toSeconds({
            h: match[1],
            m: match[2],
            s: match[3],
            ms: match[4],
        })
        const end = toSeconds({
            h: match[5],
            m: match[6],
            s: match[7],
            ms: match[8],
        })
        const tsIdx = lines.indexOf(tsLine)
        const text = lines
            .slice(tsIdx + 1)
            .join('\n')
            .replace(/<[^>]+>/g, '')
            .trim()
        if (text) cues.push({ start, end, text })
    }
    return cues
}

// Linear scan — fine for typical lesson VTTs (<1k cues) hit on a 250ms
// tick. Switching to binary search adds complexity for a workload that
// hasn't shown up.
export const findActiveCue = (cues: Cue[], t: number): Cue | null => {
    for (const cue of cues) {
        if (t >= cue.start && t <= cue.end) return cue
    }
    return null
}
